const fs=require('fs');const L=fs.readFileSync('all.js','utf8').split('\n');
const fns=[];L.forEach((l,i)=>{const m=/^function (\w+)/.exec(l);if(m)fns.push({n:m[1],s:i+1});});
fns.forEach((f,i)=>f.e=i+1<fns.length?fns[i+1].s-1:L.length);
const hooks=['bant','count','defter','dur','handoff','host','kitap','lib','loop','mod','notify','sant','ust','yasak'];
const map={};hooks.forEach(h=>map[h]=new Set());
fns.forEach(f=>{const body=L.slice(f.s-1,f.e).join('\n');
 for(const h of hooks){const re=new RegExp('[^a-z]'+h+'\\\\.js');if(re.test(body))map[h].add(f.n);}
 if(/\bCOUNT\b/.test(body))map.count.add(f.n);
 if(/\bHANDOFF\b/.test(body))map.handoff.add(f.n);
});
for(const h of hooks)console.log(h+'.js: '+([...map[h]].join(', ')||'— YOK'));
